PRAGMA foreign_keys = ON;
CREATE TABLE stores(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',photo TEXT NOT NULL DEFAULT '',accent TEXT NOT NULL DEFAULT '#6d4aff',support_email TEXT NOT NULL DEFAULT '',socials TEXT NOT NULL DEFAULT '{}',audience TEXT NOT NULL DEFAULT '',goals TEXT NOT NULL DEFAULT '',currency TEXT NOT NULL DEFAULT 'usd',timezone TEXT NOT NULL DEFAULT 'America/Chicago',stripe_account TEXT UNIQUE,payments_ready INTEGER NOT NULL DEFAULT 0,tax_enabled INTEGER NOT NULL DEFAULT 0,demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE products(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',image TEXT NOT NULL DEFAULT '',button_label TEXT NOT NULL DEFAULT 'Get the resource',price INTEGER NOT NULL DEFAULT 0 CHECK(price>=0),kind TEXT NOT NULL DEFAULT 'resource',delivery_type TEXT NOT NULL DEFAULT 'url',delivery_url TEXT,asset_id TEXT,state TEXT NOT NULL DEFAULT 'draft',position INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX products_store ON products(store_id);
CREATE TABLE assets(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),key TEXT NOT NULL UNIQUE,name TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,ready INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE contacts(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),name TEXT NOT NULL,email TEXT NOT NULL,marketing INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX contacts_store_email ON contacts(store_id,email);
CREATE TABLE activities(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),contact_id TEXT NOT NULL REFERENCES contacts(id),product_id TEXT NOT NULL REFERENCES products(id),kind TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE discounts(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),product_id TEXT NOT NULL REFERENCES products(id),code TEXT NOT NULL,percent INTEGER NOT NULL CHECK(percent BETWEEN 1 AND 99),expires_at INTEGER NOT NULL,max_uses INTEGER NOT NULL CHECK(max_uses>0),used INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX discount_store_code ON discounts(store_id,code);
CREATE TABLE orders(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),product_id TEXT NOT NULL REFERENCES products(id),contact_id TEXT NOT NULL REFERENCES contacts(id),title TEXT NOT NULL,description TEXT NOT NULL,asset_id TEXT,delivery_url TEXT,amount INTEGER NOT NULL,currency TEXT NOT NULL,tax INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',refund_amount INTEGER NOT NULL DEFAULT 0,refunded INTEGER NOT NULL DEFAULT 0,session_id TEXT UNIQUE,payment_intent TEXT,connected_account TEXT,discount_id TEXT,discount_percent INTEGER NOT NULL DEFAULT 0,reservation_released INTEGER NOT NULL DEFAULT 0,access_hash TEXT NOT NULL,created_at INTEGER NOT NULL,paid_at INTEGER,refunded_at INTEGER);
CREATE INDEX orders_store ON orders(store_id);
CREATE TABLE views(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),product_id TEXT NOT NULL REFERENCES products(id),visitor_hash TEXT NOT NULL,day TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX view_daily ON views(store_id,product_id,visitor_hash,day);
CREATE TABLE outbox(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),order_id TEXT NOT NULL REFERENCES orders(id),payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL,locked_until INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at INTEGER NOT NULL);
CREATE TABLE email_attempts(id TEXT PRIMARY KEY,outbox_id TEXT NOT NULL REFERENCES outbox(id),status TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE webhook_events(id TEXT PRIMARY KEY,stream TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE entitlements(store_id TEXT PRIMARY KEY REFERENCES stores(id),kind TEXT NOT NULL DEFAULT 'none',status TEXT NOT NULL DEFAULT 'inactive',customer_id TEXT,subscription_id TEXT,payment_intent TEXT,paid_until INTEGER,grace_until INTEGER,updated_at INTEGER NOT NULL,last_event_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE connections(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),owner_id TEXT NOT NULL,client_id TEXT NOT NULL,name TEXT NOT NULL,revoked_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE rates(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE billing_sessions(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',session_id TEXT UNIQUE,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
